INSERT INTO posts(id,canonical_alias,status,title,subtitle,description,tags,created_at,updated_at,published_at,body_json) VALUES ('01K5D0C0MENT00000000000001','document-showcase','draft','文書のすべてを確かめる長い観察ノート','文字・構造・数式・図を保存する','文書仕様の全コンポーネントを収録した、編集と保存のための長文サンプル。','["文書仕様","Tiptap","検証"]','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"この長い記事は、文書を保存し、読み直し、編集を続けるための観察ノートです。文章の意味と表示の関係を、一つずつ確かめていきます。見出し、補足、数式、図、表を組み合わせても、原文と順番が保存されることを確認します。"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"文字と意味を記録する"}]},{"type":"paragraph","content":[{"type":"text","text":"通常の文字に続いて、"},{"type":"text","text":"重要","marks":[{"type":"bold"}]},{"type":"text","text":"、太字","marks":[{"type":"b"}]},{"type":"text","text":"、italic","marks":[{"type":"i"}]},{"type":"text","text":"、下線","marks":[{"type":"underline"}]},{"type":"text","text":"、ハイライト","marks":[{"type":"highlight"}]},{"type":"text","text":"、H"},{"type":"text","text":"2","marks":[{"type":"subscript"}]},{"type":"text","text":"O、x"},{"type":"text","text":"2","marks":[{"type":"superscript"}]},{"type":"text","text":"、"},{"type":"text","text":"強調","marks":[{"type":"italic"}]},{"type":"text","text":"、"},{"type":"text","text":"取り消した案","marks":[{"type":"strike"}]},{"type":"text","text":"、"},{"type":"text","text":"const value = 1","marks":[{"type":"code"}]},{"type":"text","text":"を配置します。これは装飾ではなく、読み手が情報を読み分ける手がかりです。"}]},{"type":"paragraph","content":[{"type":"text","text":"組合せも保持します："},{"type":"text","text":"強く伝える重要語","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":"と"},{"type":"text","text":"公式コード","marks":[{"type":"code"},{"type":"link","attrs":{"href":"https://tiptap.dev/","title":"Tiptap公式"}}]},{"type":"text","text":"。普通のリンクは"},{"type":"text","text":"仕様の入口","marks":[{"type":"link","attrs":{"href":"https://spec.commonmark.org/0.31.2/","title":"CommonMark"}}]},{"type":"text","text":"です。"}]},{"type":"paragraph","content":[{"type":"text","text":"ソース上の改行"},{"type":"softBreak"},{"type":"text","text":"は同じ段落に続きます。"},{"type":"hardBreak"},{"type":"text","text":"この行は意図して改行しています。記号 # * _ | $ と ©、絵文字🌱も文字のまま残ります。"}]},{"type":"paragraph","content":[{"type":"text","text":"小見出しは本文の情報を整理します。ページのタイトルとは区別し、見出しの階層を再読込のたびに変えないことが重要です。"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"第三階層"}]},{"type":"paragraph","content":[{"type":"text","text":"ここには具体的な観察結果を書きます。文章を編集するときにも、この深さは維持されます。"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"第四階層"}]},{"type":"paragraph","content":[{"type":"text","text":"複雑な説明の小項目にも、独立した見出しが必要です。"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"リストと引用"}]},{"type":"bulletList","attrs":{"tight":true},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"資料を読む"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"順序を決める"}]},{"type":"orderedList","attrs":{"start":3,"tight":true},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"三番目から始める"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"続く項目"}]}]}]}]}]},{"type":"orderedList","attrs":{"start":7,"tight":false},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"七番目の観察。文章の中に空行が必要な場合もあります。"}]},{"type":"paragraph","content":[{"type":"text","text":"同じ項目に属する二つ目の段落です。別の項目にはなりません。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"八番目の観察。"}]}]}]},{"type":"taskList","attrs":{"tight":true},"content":[{"type":"taskItem","attrs":{"checked":true},"content":[{"type":"paragraph","content":[{"type":"text","text":"本文の保存形式を確認する"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"表示と操作を確認する"}]},{"type":"taskList","attrs":{"tight":true},"content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"小さい画面でも確認する"}]}]}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"記録は未来の自分への手紙である。"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"引用の内側に別の引用を残すこともできます。"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"コード、文字図、数式"}]},{"type":"codeBlock","attrs":{"language":"typescript","caption":null},"content":[{"type":"text","text":"function greet(name: string) {\n\treturn `こんにちは、${name}`;  \n}\n\nconsole.log(greet(\"世界\"));"}]},{"type":"codeBlock","attrs":{"language":"unknown-language","caption":null},"content":[{"type":"text","text":"unknown syntax stays here\n  indentation and spaces  "}]},{"type":"codeBlock","attrs":{"language":null,"caption":null}},{"type":"codeBlock","attrs":{"language":"text","caption":null},"content":[{"type":"text","text":"入力 ──→ 検証 ──→ 保存\n           │\n           └──→ 診断を表示"}]},{"type":"paragraph","content":[{"type":"text","text":"インライン数式 "},{"type":"inlineMath","attrs":{"latex":"E=mc^2"}},{"type":"text","text":" と、直後が数字の "},{"type":"inlineMath","attrs":{"latex":"x"}},{"type":"text","text":"2 を区別します。"}]},{"type":"blockMath","attrs":{"latex":"\\begin{aligned}\nf(x) &= \\int_0^x t^2\\,dt \\\\\n     &= \\frac{x^3}{3}\n\\end{aligned}"}},{"type":"codeBlock","attrs":{"language":"mermaid","caption":"文書の保存と診断"},"content":[{"type":"text","text":"flowchart TD\n  A[文書を入力] --> B{検証}\n  B -->|適合| C[JSONとして保存]\n  B -->|要修正| D[原文と診断を保持]\n  C --> E[閲覧と再編集]"}]},{"type":"codeBlock","attrs":{"language":"mermaid","caption":"図の説明だよ"},"content":[{"type":"text","text":"sequenceDiagram\n  participant U as 編集者\n  participant E as エディター\n  participant D as 保存先\n  U->>E: 本文を変更\n  E->>D: JSONを保存\n  D-->>E: 保存完了"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"補足と折り畳み"}]},{"type":"callout","attrs":{"kind":"note","title":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"既定ラベルの補足です。本文は通常のブロックとして編集できます。"}]}]},{"type":"callout","attrs":{"kind":"warning","title":"消さずに確認する *重要*"},"content":[{"type":"paragraph","content":[{"type":"text","text":"対応できない入力は、見た目だけ整えて削除しないようにします。保存結果の診断が出たら、入力した情報と照らし合わせます。"}]}]},{"type":"details","attrs":{"title":"検討の詳細を見る"},"content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"折り畳み内部の見出し"}]},{"type":"paragraph","content":[{"type":"text","text":"この説明は最初は閉じています。読み手が開いた状態を文書の意味として保存しません。"}]},{"type":"callout","attrs":{"kind":"note","title":"内部の補足"},"content":[{"type":"paragraph","content":[{"type":"text","text":"コンテナを入れ子にしても構造が維持されます。"}]}]},{"type":"codeBlock","attrs":{"language":"text","caption":null},"content":[{"type":"text","text":"::: はソースの一部です\n---\n/path/to/file"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"画像と図"}]},{"type":"paragraph","content":[{"type":"text","text":"文中の通常画像 "},{"type":"image","attrs":{"src":"/assets/document-sample.svg","alt":"四つの色と線を使った文書の模式図","title":"通常画像"}},{"type":"text","text":" の位置も維持します。"}]},{"type":"paragraph","content":[{"type":"image","attrs":{"src":"/assets/document-sample.svg","alt":"クリックできる模式図","title":"画像のtitle"},"marks":[{"type":"link","attrs":{"href":"https://tiptap.dev/","title":"リンクのtitle"}}]}]},{"type":"figure","attrs":{"src":"/assets/document-sample.svg","alt":"文書の流れを示す図"},"content":[{"type":"paragraph","content":[{"type":"text","text":"図のキャプションは"},{"type":"text","text":"意味を持つ説明","marks":[{"type":"bold"}]},{"type":"text","text":"です。altとは別に編集します。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"表と境界"}]},{"type":"table","attrs":{"title":"文書要素の対応"},"content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"要素"}]}]},{"type":"tableHeader","attrs":{"align":"center","colspan":1,"